import random

class Solution:
    def __init__(self, solute_name, molar_mass, mass_solute, volume_water, volume_solution=None):
        self.solute_name = solute_name
        self.molar_mass = molar_mass
        self.mass_solute = mass_solute
        self.volume_water = volume_water
        self.volume_solution = volume_solution if volume_solution else volume_water + mass_solute / self.density()
        self.mol_solute = self.mass_solute / self.molar_mass

    def density(self):
        return 1.0  # Assume density of solution is approximately 1 g/mL

    def concentration(self):
        return self.mol_solute / self.volume_solution * 1000  # Concentration in mol/L

    def take_volume(self, volume):
        if volume > self.volume_solution:
            raise ValueError("Taken volume is greater than the available volume.")
        new_solution = Solution(self.solute_name, self.molar_mass, self.mass_solute * volume / self.volume_solution, volume)
        self.mass_solute -= new_solution.mass_solute
        self.volume_solution -= volume
        return new_solution

    def mix_with(self, other_solution):
        new_mass_solute = self.mass_solute + other_solution.mass_solute
        new_volume_water = self.volume_water + other_solution.volume_water
        new_volume_solution = self.volume_solution + other_solution.volume_solution
        return Solution(self.solute_name, self.molar_mass, new_mass_solute, new_volume_water, new_volume_solution)

def generate_problem():
